    // --------------------
    .reg .u64 a_ptr, b_ptr, c_ptr;
    .reg .u32 m, n, k;
    ld.param.u64 a_ptr, [A_ptr];
    ld.param.u64 b_ptr, [B_ptr];
    ld.param.u64 c_ptr, [C_ptr];
    ld.param.u32 m, [M];
    ld.param.u32 n, [N];
    ld.param.u32 k, [K];

    // --------------------
    // Thread indices
    // --------------------
    .reg .u32 tx, ty;
    .reg .u32 row, col;
    mov.u32 tx, %tid.x;
    mov.u32 ty, %tid.y;
    // blockIdx.x -> column, blockIdx.y -> row
    .reg .u32 bx, by;
    mov.u32 bx, %ctaid.x;
    mov.u32 by, %ctaid.y;

    // Compute global row and column
    mad.lo.u32 row, by, %ntid.y, ty;   // row = by * blockDim.y + ty
    mad.lo.u32 col, bx, %ntid.x, tx;   // col = bx * blockDim.x + tx

    // Boundary check
    setp.ge.u32 p_row_out, row, m;
    setp.ge.u32 p_col_out, col, n;
    @p_row_out bra DONE;
    @p_col_out bra DONE;

    // --------------------
    // Accumulator (fp32)
    // --------------------
    .reg .f32 acc;
    mov.f32 acc, 0.0;

    // Loop over K dimension
    .reg .u32 kk;
    mov.u32 kk, 0;
