    .reg .u64 a_index, a_addr;
    mul.lo.u64 a_index, row, k;          // row * K
    add.u64 a_index, a_index, kk;        // row*K + kk
    shl.b64 a_addr, a_index, 1;          // *2 bytes per half
    add.u64 a_addr, a_ptr, a_addr;
