    mul.lo.u64 b_index, kk, n;           // kk * N
    add.u64 b_index, b_index, col;       // kk*N + col
    shl.b64 b_addr, b_index, 1;
    add.u64 b_addr, b_ptr, b_addr;
    .reg .u16 b_half;
    ld.global.u16 b_half, [b_addr];
    .reg .f32 b_f32;
    cvt.rn.f32.f16 b_f32, b_half;

    // Multiply‑accumulate
    fma.rn.f32 acc, a_f32, b_f32, acc;

    // kk++
    add.u32 kk, kk, 1;
    bra LOOP_K;
END_LOOP_K:

    // Convert accumulator to fp16 and store
    .reg .u16 c_half;
    cvt.rn.f16.f32 c_half, acc;
    .reg .u64 c_index, c_addr;
    mul.lo.u64 c_index, row, n;          // row * N
    add.u64 c_index, c_index, col;       // row*N + col
